/**
 * Citation of Slack's presence article, shown under the client table.
 *
 * @param string $lang Landing language.
 * @return string HTML.
 */
function noaway_slack_presence_source_html( $lang ) {
	$lang = function_exists( 'noaway_i18n_normalize_lang' ) ? noaway_i18n_normalize_lang( $lang ) : 'en';
	$url  = 'https://slack.com/help/articles/201864558';
	$open = '<a href="' . esc_url( $url ) . '" rel="noopener noreferrer" target="_blank" class="text-primary font-semibold hover:underline">';
	$copy = array(
		'en'    => $open . 'Slack’s help article</a> says the desktop app sets you to away after ten minutes of inactivity, and the mobile apps set you to away when you leave the app or close it.',
		'de'    => $open . 'Slack-Hilfeartikel</a>: Die Desktop-App setzt dich nach zehn Minuten Inaktivität auf Abwesend, die mobilen Apps wenn du die App verlässt oder schließt.',
		'es'    => $open . 'Artículo de ayuda de Slack</a>: la app de escritorio te pone Ausente tras diez minutos de inactividad, y las apps móviles cuando sales de la app o la cierras.',
		'pt-br' => $open . 'Artigo de ajuda do Slack</a>: o app para computador coloca você como Ausente após dez minutos de inatividade, e os apps móveis quando você sai do app ou o fecha.',
		'fr'    => $open . 'Article d’aide Slack</a> : l’app pour ordinateur vous passe en Absent après dix minutes d’inactivité, et les apps mobiles quand vous quittez l’app ou la fermez.',
	);
	$html = isset( $copy[ $lang ] ) ? $copy[ $lang ] : $copy['en'];
	return wp_kses(
		$html,
		array(
			'a' => array(
				'href'   => array(),
				'rel'    => array(),
				'target' => array(),
				'class'  => array(),
			),
		)
	);
}
